"""Measured two-node/common-cohort comparison tables and figures."""
import json
from pathlib import Path
import pandas as pd,numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

ROOT=Path('reports/two_node_phase');CORE=['temperature_c','relative_humidity_pct','pressure_hpa','wind_speed_mps']

def main():
    r=json.loads((ROOT/'results.json').read_text());rows=[];cover=[]
    from ml.spatial_ensemble.network import distances_km
    active=pd.read_parquet('data/physics_training/hours.parquet',columns=['location_id']).location_id.unique()
    stations=pd.read_csv('data/registry/india_stations.csv');stations=stations[stations.location_id.isin(active)].sort_values('location_id');stations=stations[stations.geography_status.ne('COUNTRY_LOCATION_CONFLICT')].drop_duplicates('physical_site_id')
    positions=stations[['latitude','longitude']].to_numpy();matrix=np.array([distances_km(*p,positions) for p in positions])
    support={}
    for scope in ['national5km','himalaya20km']:
        values=[];pairs=[]
        for role in ['train2023','train2024']:
            ni=np.load(f'data/two_node_training/{scope}/k2/{role}/neighbor_ids.npy',mmap_mode='r');values.append(matrix[ni[:,0],ni[:,1]]);pairs.append(np.sort(ni,axis=1))
        d=np.concatenate(values);support[scope]={'pair_time_rows':len(d),'unique_pairs':len(np.unique(np.concatenate(pairs),axis=0)),'mesh_1_to_20_km_rows':int(((d>=1)&(d<=20)).sum()),'spacing_min_p10_p50_p90_max_km':np.percentile(d,[0,10,50,90,100]).tolist()}
    (ROOT/'pair_support.json').write_text(json.dumps(support,indent=2)+'\n')
    lines=['# Exactly two nodes: measured archive results','', '**Deployment coverage remains unverified.** Each fit/prediction uses exactly K distinct QC-valid core-weather neighbors; K=2 is a separately trained model, with 3/4/5 comparisons. Complete-core contexts require T/RH/station pressure/wind, vetted height and plausible reduced pressure. This differs from the previous partial-channel 32-neighbor cohort. No row caps; all previously acquired 2023/2024 hours are considered. Exact coordinate aliases and held-out physical sites are excluded. Query labels never enter features.','', '## Identical test-row comparison (archive diagnostics)','', '| Hold-out | K | Fit rows | Common test rows | T MAE °C | RH MAE pp | P MAE hPa | Wind MAE m/s |','|---|---:|---:|---:|---:|---:|---:|---:|']
    for c in r['common_row_comparisons']:
        e=next(e for e in r['experiments'] if e['scope']==c['scope'] and e['neighbor_count']==c['neighbor_count']);scores=[c['metrics'][t]['paired_methods']['physics_residual']['mae'] for t in CORE]
        lines.append('| '+c['scope']+' | '+str(c['neighbor_count'])+' | '+str(e['fit_rows'])+' | '+str(c['common_test_rows'])+' | '+' | '.join(f'{v:.3f}' if v is not None else '—' for v in scores)+' |')
        for target in CORE:
            m=c['metrics'][target];ens=m['paired_methods']['physics_residual']['mae']
            for method,s in m['paired_methods'].items():
                ci=s['mae_station_bootstrap_95ci'];rows.append(dict(scope=c['scope'],neighbors=c['neighbor_count'],target=target,method=method,rows=s['rows'],stations=s.get('stations',0),mae=s['mae'],rmse=s['rmse'],mae_ci_lower=ci[0] if ci else None,mae_ci_upper=ci[1] if ci else None,residual_loses_to_this_method=ens is not None and s['mae'] is not None and ens>s['mae']+1e-6,domain='common archive test cohort'))
    lines+=['', 'MAE/RMSE, whole-station-bootstrap 95% MAE intervals, baseline losses and per-target denominators: [results.csv](results.csv). These are archive diagnostics, not acceptable deployment predictions. Selection gating guarantees aggregate non-inferiority only on selection labels; test losses remain.','', '## Two-neighbor physics versus residual','', '| Hold-out | Target | Rows | Residual MAE | Physics MAE | IDW MAE | Nearest MAE | Mean MAE |','|---|---|---:|---:|---:|---:|---:|---:|']
    for e in r['experiments']:
        for c in e['test_coverage']:cover.append(dict(scope=e['scope'],neighbors=e['neighbor_count'],**c))
        if e['neighbor_count']!=2:continue
        for t in CORE:
            m=e['archive_metrics'][t];scores=m['paired_methods'];lines.append('| '+e['scope']+' | '+t+' | '+str(m['paired_rows'])+' | '+' | '.join(f'{scores[k]["mae"]:.3f}' if scores[k]['mae'] is not None else '—' for k in ['physics_residual','physics_baseline','idw','nearest_node','node_mean'])+' |')
    lines+=['', 'The two-node baseline performs fixed 6.5 K/km temperature correction, dewpoint interpolation/RH restoration, common-height log-pressure reduction and query-height restoration; wind uses IDW. Missing/suspect height/pressure remains unavailable. Physics is also a residual-model feature and fallback. PM targets stay optional/untrained.','', '## Serving eligibility and uncertainty','', '| Hold-out | K | Current geometry-eligible rows | Geometry policy |','|---|---:|---:|---|']
    for e in r['experiments']:lines.append(f'| {e["scope"]} | {e["neighbor_count"]} | {e["geometry_eligible_rows"]} | '+('A–B corridor' if e['neighbor_count']==2 else '20 km + hull')+' |')
    lines+=['', 'Default corridor: ≤1 km from the clamped A–B segment, ≤0.25 km beyond either end, pair separation ≤20 km. End and segment distances both apply; co-located/antipodal endpoints are refused. Configurable flag-only extrapolation emits a flagged prediction and no checked band. Missing contributors remain refused even in flag mode.','', '**Zero two-node test rows satisfy the default corridor**. NOAA complete-four-channel nearest pairs are too widely separated; actual minimum national test A–B spacing is documented below. Training counts do not prove close-range support. For 3–5 nodes the hull policy is different, so geometry-subset scores cannot rank deployment policies fairly. Common archive-row comparisons above are the controlled neighbor-count comparison.','', 'Bands are fit with whole global 72-hour blocks Sep–Oct, independently checked Nov and revoked on December audit failures. All rows used for band calibration/check/audit must pass the corresponding serving geometry. **No two-node checked 80/90% band is available**; demo outputs null, never a 3–5-node or 32-node band. Full trial coverage/widths/counts: [coverage_by_distance.csv](coverage_by_distance.csv). Calendar blocks are episode proxies and future/field coverage is unverified. Hourly archive bands also require completed-hour input metadata and unchanged corridor limits.','', '## Commands and verified behavior','', '- Node collection/calibration/position rotation: [NODE_COLLECTION_SPEC.md](../nwic_pipeline/NODE_COLLECTION_SPEC.md). Frozen per-instrument offsets are fit only from a previous colocated session; no deployment-label fitting.', '- `python -m reports.practicum.demo --input reports/two_node_phase/examples/readings.json --model data/two_node_training/national5km/k2/model.json`. Input contains exactly A/B plus query metadata; hidden readings and third nodes are rejected. Models are bounded JSON, never pickle.', '- `python -m ml.field.two_node calibrate colocated.csv --output offsets.json`; `python -m ml.field.two_node score field.csv --offsets offsets.json --output scores.csv --model data/two_node_training/national5km/k2/model.json`. Default hides A/B/C in turn; `--hide-c-only` matches deployment. All refusal/missing counts and raw/corrected truth are retained. Unguarded IDW/nearest/mean diagnostics have separate availability.', '- Side-by-side offset and hidden-label-independence tests pass; the CLI calibration/scoring and physics/model demos were executed on **synthetic fixtures only**. No physical field observations supplied.', '- JSON round trips checked against sklearn over every test row: maximum prediction deviation across runs '+f'{max(e["artifact_roundtrip_max_abs_error"] for e in r["experiments"]):.8f}'+'. Missing-only HGB splits are represented explicitly, not as invalid JSON infinities. No executable deserialization.', '- Use isolated `requirements-physics.txt`; `python -m ml.spatial_ensemble.evaluate_two_nodes` reproduces all eight experiments without caps. Trained JSON files/feature arrays remain local under ignored `data/two_node_training/`; source hashes and artifact hashes are in [results.json](results.json).','', '## Limits and next evidence','', 'Archive context pairs can change with availability; the deployed A/B instruments are fixed. Whole-station/5 km national and 20 km Himalaya-proxy buffers, disjoint global time blocks, prior QC and masked heads are preserved. The Himalaya proxy is the previous lat/lon/elevation definition, not a complete ecological boundary. Core pressure availability selects a sparse cohort; nearby airport/WMO aliases beyond exact coordinates remain unresolved. More neighbors are not a uniform improvement; humidity and residual-pressure losses are explicitly preserved in CSV.','', 'Offsets are relative to C unless a traceable instrument/reference is supplied; they cannot establish absolute accuracy, gain/linearity, high-wind behavior or drift. Fixed-position endpoint hiding is extrapolation; rotate physical instruments through the middle position in separate episodes for an interpolation comparison. Do not treat three rotations from the same episode as independent evidence.','', 'Before a deployment claim: collect the A/B/C campaign, score untouched field episodes at real spacing/elevation/exposure, calibrate and check field-domain bands independently, and measure device memory/latency/watchdog/precision. The JSON evaluator is Python/server code; ESP32 execution remains unverified. ERA5/PM training and real authentication/transport integration are not added in this phase.','', '![Common-row MAE by neighbor count](neighbor_comparison.png)','']
    for scope in ['national5km','himalaya20km']:
        f=np.load(f'data/two_node_training/{scope}/k2/test_predictions.npz');p=np.percentile(f['node_separation_km'],[0,10,50,90,100]);lines.insert(lines.index('## Commands and verified behavior'),f'A–B spacing {scope}, min/p10/median/p90/max: '+', '.join(f'{v:.2f}' for v in p)+' km; pairs ≤20 km: '+str(int((f['node_separation_km']<=20).sum()))+'.\n')
        v=support[scope];lines.insert(lines.index('## Commands and verified behavior'),f'Training {scope}: {v["pair_time_rows"]} pair-time rows / {v["unique_pairs"]} unique A–B pairs; {v["mesh_1_to_20_km_rows"]} rows have 1–20 km A–B spacing. [Pair support](pair_support.json).\n')
    pd.DataFrame(rows).to_csv(ROOT/'results.csv',index=False);pd.DataFrame(cover).to_csv(ROOT/'coverage_by_distance.csv',index=False);(ROOT/'REPORT.md').write_text('\n'.join(lines))
    df=pd.DataFrame(rows);fig,axes=plt.subplots(2,4,figsize=(14,7))
    for row,scope in enumerate(['national5km','himalaya20km']):
        for col,target in enumerate(CORE):
            ax=axes[row,col]
            for method,label in [('physics_residual','Residual'),('physics_baseline','Physics'),('idw','IDW')]:
                q=df[(df.scope==scope)&(df.target==target)&(df.method==method)].sort_values('neighbors');ax.plot(q.neighbors,q.mae,'o-',label=label)
            ax.set_title(scope+'\n'+target);ax.set_xticks([2,3,4,5]);ax.set_xlabel('Exactly K complete-core nodes');ax.set_ylabel('MAE (target units)');ax.grid(alpha=.2)
    axes[0,0].legend();fig.suptitle('Identical archive test rows; outside deployment corridor is not serving evidence');fig.tight_layout();fig.savefig(ROOT/'neighbor_comparison.png',dpi=180);fig.savefig(ROOT/'neighbor_comparison.pdf');plt.close(fig)
if __name__=='__main__':main()
